import { action } from "solid-js";
const run = () => { void action(function* () {})(); };
// A built-in's prototype written by assignment: every Float32Array inherits the replaced method.
const reverse = Float32Array.prototype.reverse;
Float32Array.prototype.reverse = function () {
  run();
  return reverse.call(this);
};
// A global written by name (ADR 0974), unchanged by ADR 1108.
const atob = globalThis.atob;
globalThis.atob = (text) => {
  run();
  return atob(text);
};
